package external

import (
	"net/http"
	"strconv"

	externalapi "github.com/mokevnin/1mail/gen/external"
	"github.com/mokevnin/1mail/internal/accounts"
	"github.com/mokevnin/1mail/internal/api/external/resources"
	"github.com/mokevnin/1mail/internal/automations"
	"github.com/mokevnin/1mail/internal/broadcasts"
	"github.com/mokevnin/1mail/internal/contacts"
	"github.com/mokevnin/1mail/internal/erasure"
	"github.com/mokevnin/1mail/internal/eventlog"
	"github.com/mokevnin/1mail/internal/events"
	"github.com/mokevnin/1mail/internal/integrations"
	"github.com/mokevnin/1mail/internal/outbound"
	"github.com/mokevnin/1mail/internal/reputation"
	"github.com/mokevnin/1mail/internal/secrets"
	"github.com/mokevnin/1mail/internal/segments"
	"github.com/mokevnin/1mail/internal/sendingdomains"
	"github.com/mokevnin/1mail/internal/tags"
)

// mapper turns ent entities into external API resources (generated by goverter).
var mapper = &resources.ConverterImpl{}

type Handlers struct {
	externalapi.UnimplementedHandler
	accounts       *accounts.Accounts
	bus            *events.Bus
	eventlog       *eventlog.Module
	outbound       *outbound.Module
	segments       *segments.Module
	cipher         *secrets.Cipher
	integrations   *integrations.Module
	sendingDomains *sendingdomains.Module
	broadcasts     *broadcasts.Module
	reputation     *reputation.Module
	contacts       *contacts.Module
	erasure        *erasure.Module
	tags           *tags.Module
	automations    *automations.Module
	bootstrapToken string
}

// Deps is everything the /api handlers are built from. The domain modules are
// the shared singletons the composition root registers once, so /api and /site
// cannot diverge on how a module is constructed.
type Deps struct {
	Accounts       *accounts.Accounts
	Bus            *events.Bus
	Cipher         *secrets.Cipher
	Integrations   *integrations.Module
	SendingDomains *sendingdomains.Module
	Outbound       *outbound.Module
	Segments       *segments.Module
	EventLog       *eventlog.Module
	Contacts       *contacts.Module
	Erasure        *erasure.Module
	Tags           *tags.Module
	Automations    *automations.Module
	Broadcasts     *broadcasts.Module
	Reputation     *reputation.Module
	BootstrapToken string
}

func NewHandlers(d Deps) *Handlers {
	return &Handlers{
		accounts: d.Accounts, bus: d.Bus, cipher: d.Cipher, integrations: d.Integrations, sendingDomains: d.SendingDomains, outbound: d.Outbound, segments: d.Segments,
		eventlog: d.EventLog, contacts: d.Contacts, erasure: d.Erasure, tags: d.Tags, automations: d.Automations,
		broadcasts: d.Broadcasts, reputation: d.Reputation, bootstrapToken: d.BootstrapToken,
	}
}

var _ externalapi.Handler = (*Handlers)(nil)

// problem builds a ProblemDetails value for the given status code and detail.
func problem(code int, detail string) externalapi.ProblemDetails {
	return externalapi.ProblemDetails{
		Status: externalapi.NewOptInt32(int32(code)),
		Title:  externalapi.NewOptString(http.StatusText(code)),
		Detail: externalapi.NewOptString(detail),
	}
}

// parseEntityID parses an EntityId into an int64.
func parseEntityID(id externalapi.EntityId) (int64, error) {
	return strconv.ParseInt(string(id), 10, 64)
}
